/**
 * Fixtures for the hermetic suite. `fixtures/` is generated by
 * `deno task vendor:sync` from the device repo — never edit it by hand.
 */

import { codec, type DecodedMessage } from "hour-meter";

interface FrameFixtures {
  /** `esp32/docs/FRAME-CATALOG.md`, keyed by `<!-- frame:<id> -->`. */
  catalog: Record<string, string>;
  /** `esp32/docs/INTEGRATION-GUIDE.md`, keyed by `<!-- golden:<id> -->`. */
  golden: Record<string, string>;
}

const FRAMES: FrameFixtures = JSON.parse(
  await Deno.readTextFile(new URL("./fixtures/frames.json", import.meta.url)),
);

export function hex(text: string): Uint8Array {
  return Uint8Array.from(text.match(/../g) ?? [], (b) => parseInt(b, 16));
}

/** A firmware-accurate wire frame (COBS + trailing 0x00) from the catalog. */
export function catalogFrame(id: string): Uint8Array {
  const frame = FRAMES.catalog[id];
  if (frame === undefined) throw new Error(`no catalog frame '${id}'`);
  return hex(frame);
}

export function decodeCatalog(id: string): DecodedMessage {
  return codec.decodeFrame(catalogFrame(id));
}

/** The catalog's devices: deviceId 0x1a2b3c4d, device clock 2026-10-07T12:34:56Z. */
export const DEVICE_ID = 0x1a2b3c4d;
export const DEVICE_EPOCH = 1_791_376_496;

/** Counters as in the catalog's TELEMETRY frame. */
export const TELEMETRY_VALUES = {
  runSeconds: 4_500_000,
  totalCount: 15_000,
  alternator: true,
  runHours: 1250,
  totalUnits: 15_000,
  timeValid: true,
  statusFlags: 0,
};

export interface FrameHeader {
  msgType?: number;
  seq?: number;
  deviceId?: number;
  timestamp?: number;
}

/**
 * A wire frame built by the vendored codec, for cases the catalog lacks.
 * `extra` adds records by raw tag/fmt — e.g. a tag this firmware never sends.
 */
export function buildFrame(
  values: Record<string, number | boolean>,
  header: FrameHeader = {},
  extra: Array<{ tag: number; fmt: string; value: number }> = [],
): Uint8Array {
  const message = {
    msgType: 1,
    seq: 1,
    deviceId: DEVICE_ID,
    timestamp: DEVICE_EPOCH,
    ...header,
    values,
    records: extra,
  };
  return codec.frame(message);
}

export function decodeBuilt(
  ...args: Parameters<typeof buildFrame>
): DecodedMessage {
  return codec.decodeFrame(buildFrame(...args));
}

export const sleep = (ms: number) =>
  new Promise<void>((resolve) => setTimeout(resolve, ms));

/** Collect unhandled rejections instead of letting them kill the runner. */
export function collectRejections() {
  const seen: unknown[] = [];
  const onRejection = (event: PromiseRejectionEvent) => {
    seen.push(event.reason);
    event.preventDefault();
  };
  globalThis.addEventListener("unhandledrejection", onRejection);
  return {
    seen,
    stop: () =>
      globalThis.removeEventListener("unhandledrejection", onRejection),
  };
}
